I'd add one middleware, register it first in `app.js`, and have it write a single JSON line per request once the response closes. None of the route files change, and new routes get logged automatically. I tested this on Express 5.2.1 with a stand-in for `sessionUser`, and I haven't touched your project.

## The middleware

A new `logging.js` next to `auth.js`:

```js
const { randomUUID } = require("crypto");

// One JSON line per request, written when the response closes. Fields are an
// explicit allowlist: never log headers (the session cookie is a login) or bodies.
function requestLog(req, res, next) {
  const start = process.hrtime.bigint();
  const incoming = req.get("x-request-id");
  req.id = incoming && /^[\w-]{1,64}$/.test(incoming) ? incoming : randomUUID();
  res.set("X-Request-Id", req.id);

  res.on("close", () => {
    console.log(JSON.stringify({
      time: new Date().toISOString(),
      reqId: req.id,
      method: req.method,
      path: req.originalUrl.split("?")[0],
      status: res.headersSent ? res.statusCode : null,
      aborted: !res.writableFinished,
      ms: Number(process.hrtime.bigint() - start) / 1e6,
      userId: req.user && req.user.id,
      accountId: req.user && req.user.accountId,
    }));
  });
  next();
}

module.exports = { requestLog };
```

And in `app.js`, register it before everything else:

```js
app.use(requestLog);
app.use(express.json());
app.use(sessionUser);
```

